def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    top = [c for c, v in enumerate(grid[0]) if v != 0]
    if len(top) < 3:
        return out

    left_col, mid_col, right_col = top[0], top[len(top)//2], top[-1]
    left_color, mid_color, right_color = (
        grid[0][left_col], grid[0][mid_col], grid[0][right_col]
    )

    # The middle color runs the full height.
    for r in range(h):
        out[r][mid_col] = mid_color

    # Outer colors connect their top marker to the matching marker on the
    # corresponding side of the grid.
    left_rows = [r for r in range(1, h) if grid[r][0] == left_color]
    if left_rows:
        r = left_rows[0]
        for rr in range(r + 1):
            out[rr][left_col] = left_color
        for c in range(left_col + 1):
            out[r][c] = left_color

    right_rows = [r for r in range(1, h) if grid[r][w - 1] == right_color]
    if right_rows:
        r = right_rows[0]
        for rr in range(r + 1):
            out[rr][right_col] = right_color
        for c in range(right_col, w):
            out[r][c] = right_color

    return out
